def solve_small(n):
    # Brute force is too slow for n=5.
    # Let's try a simple greedy or random search.
    import random
    best_k = 0
    for _ in range(1000):
        picked = set()
        all_squares = [(r, c) for r in range(n) for c in range(n)]
        random.shuffle(all_squares)
        for r, c in all_squares:
            # Try adding (r, c)
            picked.add((r, c))
            # Check if adding (r, c) violates the condition
            # 1. (r, c) must have degree <= 1
            # 2. All neighbors of (r, c) must still have degree <= 1
            valid = True
            # Degree of (r, c)
            deg_rc = 0
            for nr, nc in get_neighbors(r, c, n):
                if (nr, nc) in picked:
                    deg_rc += 1
            if deg_rc > 1:
                valid = False
            else:
                # Degree of neighbors
                for nr, nc in get_neighbors(r, c, n):
                    if (nr, nc) in picked:
                        deg_n = 0
                        for nnr, nnc in get_neighbors(nr, nc, n):
                            if (nnr, nnc) in picked:
                                deg_n += 1
                        if deg_n > 1:
                            valid = False
                            break
            if not valid:
                picked.remove((r, c))
        best_k = max(best_k, len(picked))
    return best_k

