def solve_small_simulated_annealing(n):
    # Simulated Annealing to find a larger k
    current_picked = set()
    # Start with a greedy solution
    all_squares = [(r, c) for r in range(n) for c in range(n)]
    random.shuffle(all_squares)
    for r, c in all_squares:
        current_picked.add((r, c))
        valid = True
        deg_rc = 0
        for nr, nc in get_neighbors(r, c, n):
            if (nr, nc) in current_picked:
                deg_rc += 1
        if deg_rc > 1:
            valid = False
        else:
            for nr, nc in get_neighbors(r, c, n):
                if (nr, nc) in current_picked:
                    deg_n = 0
                    for nnr, nnc in get_neighbors(nr, nc, n):
                        if (nnr, nnc) in current_picked:
                            deg_n += 1
                    if deg_n > 1:
                        valid = False
                        break
        if not valid:
            current_picked.remove((r, c))

    best_picked = set(current_picked)

    # Annealing
    temp = 1.0
    cooling_rate = 0.999
    for _ in range(10000):
        # Try to add a square or remove one
        r, c = random.randint(0, n-1), random.randint(0, n-1)
        if (r, c) in current_picked:
            current_picked.remove((r, c))
        else:
            current_picked.add((r, c))
            # Check if current_picked is valid
            # To keep it efficient, only check the neighbors of (r, c)
            valid = True
            deg_rc = 0
            for nr, nc in get_neighbors(r, c, n):
                if (nr, nc) in current_picked:
                    deg_rc += 1
            if deg_rc > 1:
                valid = False
            else:
                for nr, nc in get_neighbors(r, c, n):
                    if (nr, nc) in current_picked:
                        deg_n = 0
                        for nnr, nnc in get_neighbors(nr, nc, n):
                            if (nnr, nnc) in current_picked:
                                deg_n += 1
                        if deg_n > 1:
                            valid = False
                            break
            if not valid:
                current_picked.remove((r, c))

        if len(current_picked) > len(best_picked):
            best_picked = set(current_picked)
        temp *= cooling_rate

    return len(best_picked)

