def test_pattern(n, pattern_func):
    picked = set()
    for r in range(n):
        for c in range(n):
            if pattern_func(r, c):
                picked.add((r, c))

    # Check if valid
    for r, c in picked:
        deg = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and (nr, nc) in picked:
                    deg += 1
        if deg > 1:
            return False, len(picked)
    return True, len(picked)

# Pattern: r+c = 0 mod 3 and r even
def pattern1(r, c):
    return (r + c) % 3 == 0 and r % 2 == 0

# Pattern: r+c = 0 mod 3 and r odd
def pattern2(r, c):
    return (r + c) % 3 == 0 and r % 2 != 0

# Pattern: r = 0 mod 3 and c = 0, 1 mod 3
def pattern3(r, c):
    return r % 3 == 0 and c % 3 != 2

for n in range(1, 11):
    v1, k1 = test_pattern(n, pattern1)
    v2, k2 = test_pattern(n, pattern2)
    v3, k3 = test_pattern(n, pattern3)
    print(f"n={n}, p1={k1 if v1 else 'X'}, p2={k2 if v2 else 'X'}, p3={k3 if v3 else 'X'}")

